#!/usr/bin/env texlua
-- Derives the bundle README for CTAN (ctan/README.md) from the GitHub
-- README.md.  The result is a static snapshot of the release: it is
-- regenerated by "l3build tag" in the bundle root and committed, and
-- "l3build ctan" refuses to package a snapshot that no longer matches.
--
-- Usage: texlua tools/make-ctan-readme.lua [--check]   (run from the bundle root)
--
-- Transformations, in this order:
--   - <!-- BEGIN GITHUB ONLY --> ... <!-- END GITHUB ONLY --> is dropped,
--   - the body of a <!-- CTAN ONLY ... --> comment is inserted as text,
--     with @RELEASEDATE@ replaced by the bundle release date,
--   - every other HTML comment is removed (marker contents are kept),
--   - GitHub alerts ("> [!WARNING]") become a bold label,
--   - GitHub emoji shortcodes become UTF-8 emoji; an unknown shortcode
--     is an error, so a new icon cannot slip through unnoticed,
--   - repository paths after a module name (" (`./ollm`)") are removed,
--   - the module table loses its "TL ..." columns, their footnotes, and
--     the rows that only state a compatibility (version "n/a"): they
--     describe installations from the repository on older TeX Live
--     releases, while a distribution ships the bundle for the current one.

local SOURCE = "README.md"
local TARGET = "ctan/README.md"

local EMOJI = {
  full_moon          = "🌕",
  first_quarter_moon = "🌓",
  new_moon           = "🌑",
  white_circle       = "⚪",
  red_circle         = "🔴",
  green_circle       = "🟢",
}

local versions = dofile("tools/bundle-versions.lua")
local read_file = versions.read_file

local function fail(message)
  io.stderr:write("make-ctan-readme: " .. message .. "\n")
  os.exit(1)
end

local function split_row(line)
  local cells = { }
  for cell in line:gsub("^|", ""):gsub("|%s*$", ""):gmatch("([^|]*)|?") do
    table.insert(cells, (cell:gsub("^%s+", ""):gsub("%s+$", "")))
  end
  if cells[#cells] == "" then
    table.remove(cells)
  end
  return cells
end

local function strip_compatibility(content)
  local lines, keep = { }, nil
  for line in (content .. "\n"):gmatch("([^\n]*)\n") do
    if line:match("^| Module |") then
      keep = { }
      for i, cell in ipairs(split_row(line)) do
        keep[i] = not cell:match("^TL ")
      end
    end
    if keep and line:match("^|") then
      local cells, kept = split_row(line), { }
      for i, cell in ipairs(cells) do
        if keep[i] then
          table.insert(kept, (cell:gsub("%[%^%d+%]", "")))
        end
      end
      if kept[2] ~= "n/a" then
        table.insert(lines, "| " .. table.concat(kept, " | ") .. " |")
      end
    elseif keep and line:match("^%[%^%d+%]:") then
      -- footnote of a compatibility entry
    else
      if keep and not line:match("^|") then
        keep = nil
      end
      table.insert(lines, line)
    end
  end
  return table.concat(lines, "\n")
end

local function generate(content)
  local release_date = content:match(
    "<!%-%- BUNDLE RELEASE DATE %-%->(.-)<!%-%- /BUNDLE RELEASE DATE %-%->"
  ) or "unreleased"

  content = content:gsub("\r\n", "\n")

  content = content:gsub(
    "<!%-%- BEGIN GITHUB ONLY %-%->.-<!%-%- END GITHUB ONLY %-%->\n?", ""
  )
  content = content:gsub("<!%-%- CTAN ONLY[ \t]*\n(.-)%-%->", function(body)
    return (body:gsub("@RELEASEDATE@", release_date))
  end)
  content = content:gsub("<!%-%-.-%-%->", "")
  content = strip_compatibility(content)

  content = content:gsub("\n>%s*%[!(%u+)%]%s*\n", function(kind)
    return "\n> **" .. kind:sub(1, 1) .. kind:sub(2):lower() .. "**\n"
  end)

  local unknown = { }
  content = content:gsub(":(%l[%l%d_]*):", function(name)
    if EMOJI[name] then
      return EMOJI[name]
    end
    table.insert(unknown, name)
  end)
  if #unknown > 0 then
    fail("no replacement for emoji shortcode(s) :"
      .. table.concat(unknown, ":, :") .. ": (add them to EMOJI)")
  end

  content = content:gsub(" %(`%./[^`]+`%)", "")

  -- Removed blocks leave runs of blank lines and trailing blanks behind.
  content = content:gsub("[ \t]+\n", "\n")
  content = content:gsub("\n\n\n+", "\n\n")
  content = content:gsub("^\n+", ""):gsub("\n*$", "\n")

  return "<!-- Generated from README.md by tools/make-ctan-readme.lua;"
    .. " do not edit. -->\n" .. content
end

local check = arg[1] == "--check"
if arg[1] and not check then
  fail("unknown argument " .. arg[1])
end

local source = read_file(SOURCE) or fail("cannot read " .. SOURCE)
local result = generate(source)

if check then
  if read_file(TARGET) ~= result then
    fail(TARGET .. " does not match " .. SOURCE
      .. "; run 'texlua tools/make-ctan-readme.lua' (or 'l3build tag')")
  end
  print(TARGET .. " is up to date")
  os.exit(0)
end

local handle = io.open(TARGET, "wb") or fail("cannot write " .. TARGET)
handle:write(result)
handle:close()
print("Wrote " .. TARGET)
